  ],
  "claims": [
    {
      "claim": "Transferable human absolute oral bioavailability measurements for structurally similar high-MW, high-TPSA, ionized compounds are consistently below 20%: nintedanib ~4.7–5%, remikiren 0.2–0.3%, DX-9065a 2–3%, melagatran 3–7%, astemizole 3%, rebamipide <10%, and MK-458 ~4–5%.",
      "card_ids": ["C01","C03","C05","C07","C10","C11","C14","C16","C17","C20","C02"]
    },
    {
      "claim": "L2 records add further low-F context: remikiren <1.0% at 200 mg oral; DX-9065a 5–10% in animals, 5–12% in baboons, and 10.8±2.0% in fasted rats; melagatran-class peptidomimetics are not orally bioavailable due to poor enteral absorption and presystemic extraction; PHNO is low; DX-9065 capsule is limited in the fasted state.",
      "card_ids": ["C23","C28","C31","C32","C35","C36","C39"]
    },
    {
      "claim": "The low-F contexts attribute poor oral F to strong basic/ionizable groups and first-pass extraction (DX-9065a, melagatran), consistent with the query's predominantly ionized state at pH 7.4 (neutral fraction 0.01) and high TPSA.",
      "card_ids": ["C05","C32"]
    },
    {
      "claim": "L3 oral exposure records are for unrelated reference molecules and mostly lack IV comparators or involve special routes/formulations/boosting (DHE MAP0004, indinavir/ritonavir, saquinavir/ritonavir or nelfinavir, granisetron, lopinavir); they do not provide direct absolute F for the query and cannot affirm F >= 20%.",
      "card_ids": ["C40","C41","C42","C43","C44","C45","C46","C47","C48","C49","C50","C51"]
    },
    {
      "claim": "The only L3 card for a molecule with a known low human F (rebamipide, C45) shows a rat Cmax for an optimized formulation, which does not contradict the human F <10% context (C11).",
      "card_ids": ["C45","C11"]
    },
    {
      "claim": "High-exposure L3 records (DHE MAP0004 AUC ratios ~40%, boosted indinavir/saquinavir) are route/formulation/boosting-dependent and not transferable to the query's unboosted oral absorption; they do not overturn the transferable human low-F evidence.",
      "card_ids": ["C40","C43","C46","C47","C49","C51","C50","C48","C44"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C40","C41","C42","C43","C44","C45","C46","C47","C48","C49","C50","C51"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "No human IV comparator or matched oral exposure data are available for the query.",
    "No measured permeability, solubility, or first-pass extraction data are available for the query.",
    "L3 oral AUC/Cmax records are for other molecules and do not provide query-specific F.",
    "Animal and formulation-dependent higher-F records are not directly transferable to human oral F for this query."
  ],
  "decision_summary": "Predicted low (F < 20%) because multiple transferable human low-F contexts and the query's large, highly ionized, high-TPSA structure support poor oral bioavailability; L3 oral exposure records are mostly non-query-specific exposure values without IV comparators or with special routes/boosting, so they do not provide affirmative evidence for F >= 20% and do not change the prior low decision. Confidence remains moderate due to lack of direct query-specific PK data."
}

